'use client';

import { useEffect, useRef, useState, type ReactNode } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './sticky-section-story.css';

export interface StoryStep {
  id: string;
  title: string;
  text: string;
}

export interface StickySectionStoryProps {
  steps: StoryStep[];
  /** Draws the pinned picture for the active step. */
  renderVisual: (index: number) => ReactNode;
  /** Accessible name for the story. */
  label: string;
  className?: string;
}

/**
 * A picture stays pinned while captions scroll past it inside the story's
 * own scroll area, and the picture follows the caption in view. Numbered
 * buttons jump straight to a caption.
 */
export function StickySectionStory({
  steps,
  renderVisual,
  label,
  className = '',
}: StickySectionStoryProps) {
  const scroller = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(0);
  const reduced = useReducedMotion();

  useEffect(() => {
    const el = scroller.current;
    if (!el) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      const line = el.scrollTop + el.clientHeight * 0.45;
      let index = 0;
      el.querySelectorAll<HTMLElement>('[data-step]').forEach((step, i) => {
        if (step.offsetTop <= line) index = i;
      });
      setActive(index);
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };
    update();
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      el.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(frame);
    };
  }, [steps]);

  const jump = (index: number) => {
    const el = scroller.current;
    const step = el?.querySelector<HTMLElement>(`[data-step="${index}"]`);
    if (el && step)
      el.scrollTo({
        top: step.offsetTop - el.clientHeight * 0.2,
        behavior: reduced ? 'auto' : 'smooth',
      });
  };

  return (
    <div className={`mg-story ${className}`}>
      <div
        ref={scroller}
        className='mg-story__scroller'
        tabIndex={0}
        role='region'
        aria-label={label}
      >
        <div className='mg-story__layout'>
          <div className='mg-story__pin' aria-hidden='true'>
            {renderVisual(active)}
          </div>
          <ol className='mg-story__steps'>
            {steps.map((step, index) => (
              <li
                key={step.id}
                data-step={index}
                data-active={index === active}
                className='mg-story__step'
              >
                <h4>{step.title}</h4>
                <p>{step.text}</p>
              </li>
            ))}
          </ol>
        </div>
      </div>
      <div
        className='mg-story__jumps'
        role='group'
        aria-label={`${label}: jump to a step`}
      >
        {steps.map((step, index) => (
          <button
            key={step.id}
            type='button'
            aria-current={index === active ? 'step' : undefined}
            aria-label={`Step ${index + 1}: ${step.title}`}
            onClick={() => jump(index)}
          >
            {index + 1}
          </button>
        ))}
        <span className='mg-story__now'>
          Step {active + 1} of {steps.length}: {steps[active]?.title}
        </span>
      </div>
    </div>
  );
}

.mg-story {
  display: grid;
  gap: 10px;
  color: var(--mg-text, #ffffff);
}

.mg-story__scroller {
  /* Children measure their offsets from here. */
  position: relative;
  height: 230px;
  overflow-y: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
}

.mg-story__scroller:focus-visible {
  outline: 3px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

.mg-story__layout {
  display: grid;
  grid-template-columns: 44% 1fr;
  gap: 12px;
  padding: 0 12px;
}

.mg-story__pin {
  position: sticky;
  top: 0;
  align-self: start;
  height: 228px;
  display: grid;
  place-items: center;
}

.mg-story__steps {
  margin: 0;
  padding: 90px 0 120px;
  list-style: none;
}

.mg-story__step {
  min-height: 150px;
  opacity: 0.35;
  transition: opacity 300ms ease;
}

.mg-story__step[data-active='true'] {
  opacity: 1;
}

.mg-story__step h4 {
  margin: 0 0 4px;
  font-size: 15px;
}

.mg-story__step p {
  margin: 0;
  color: #b8b8b8;
  font-size: 13px;
}

.mg-story__jumps {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.mg-story__jumps button {
  width: 40px;
  height: 40px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 50%;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.mg-story__jumps button[aria-current] {
  border-color: var(--mg-text, #ffffff);
  background: var(--mg-raised, #262626);
  color: #fff;
}

.mg-story__jumps button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

.mg-story__now {
  color: #b8b8b8;
  font-size: 13px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-story__step {
    transition: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
